class PackageLed extends Led{set(state){super.set(state);this.glow.visible=false;}}
const connectorDrills=[...[-4.95,4.95].flatMap(x=>[-3,-1,1,3].map(y=>[x,y])),...[-3,-1,1,3].map(x=>[x,-11.3])];
function circuit(host){const black=materials.plastic(0x20231f,{roughness:.85}),gold=materials.metal(0xaaaa48,{roughness:.68}),tin=materials.metal(0xb7bcb0,{roughness:.43}),pcb=solid(host.body,boardShape(connectorDrills),1,[0,0,-.5],black,'NeoHEX own dimensioned1mm six-ear PCB,6real mount bores/6breakaway slots/12Grove drills'),pads=[],barrels=[],capacitors=[],terminals=[];pcb.userData={role:'physical-pcb',source:'OwnA045-B dimension/photo parameterization;not borrowedHEX CAD'};
 for(const[x,y]of mountingCenters){barrels.push(ring(host.body,1.06,1,1,[x,y,-.5],gold,'NeoHEX actual Ø2 mounting copper barrel'));for(const z of[-.508,.5])pads.push(ring(host.body,2,1,.008,[x,y,z],gold,'NeoHEX actual six-ear annular exposed copper'));}
 for(const[x,y]of connectorDrills){barrels.push(ring(host.body,.36,.32,1,[x,y,-.5],tin,'NeoHEX actual Grove plated barrel'));for(const z of[-.525,.5])pads.push(ring(host.body,.58,.32,.025,[x,y,z],tin,'NeoHEX actual Grove solder land'));}
 const locations=[...[-7.5,-2.5,2.5,7.5].flatMap(x=>[[x,13],[x,10]]),...[-7.5,-2.5,2.5,7.5].map(x=>[x,-13]),[9.9,-7.8]];for(const[i,[x,y]]of locations.entries()){capacitors.push(box(host.body,[.67,1.35,.5],[x,y,-.75],materials.plastic(0xafa887,{roughness:.8}),'NeoHEX actual C'+(i+1)+'100nF decoupling envelope;photo-derived placement'));for(const sy of[-1,1])terminals.push(box(host.body,[.72,.28,.22],[x,y+sy*.61,-.62],tin,'NeoHEX fixed capacitor solder end'));}return{pcb,pads,barrels,capacitors,terminals,connectorDrills,mountingCenters};}
function socket(host,id){const p=spec.ports[id],frame=new THREE.Group();frame.name='NeoHEX actual '+id+' white Grove-form receiving socket';frame.position.fromArray(p.position);frame.quaternion.copy(portQuaternion(p.face));host.body.add(frame);const white=materials.plastic(0xe3e3d8,{roughness:.7}),tin=materials.metal(0xb8bdab,{roughness:.42}),depth=id==='grove-in'?7.7:6.3,parts=[],contacts=[],returns=[],tails=[];const b=(size,pos,name,mat=white)=>{const o=box(frame,size,pos,mat,'NeoHEX '+id+' '+name);parts.push(o);return o;};
 for(const sign of[-1,1]){b([.65,depth,5.1],[sign*4.675,-depth/2,0],'actual side wall');b([.65,3.1,.5],[sign*3.85,-depth+1.7,2.3],'actual guide rail');b([.6,1.15,.4],[sign*3.65,-1.9,2.35],'actual latch shoulder');}const floor=b([8.7,depth,.65],[0,-depth/2,-2.225],'closed socket floor'),back=b([8.7,.65,4.45],[0,-depth+.325,.325],'actual deep dielectric backstop'),bridge=b([4.8,2.3,.45],[0,-depth+1.5,2.325],'actual fixed locking bridge');
 for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(b([.42,depth-1.6,.42],[x,-depth/2-.4,.15],'actual receiving contact'+(i+1),tin));if(id==='grove-in'){returns.push(b([.42,.42,3.05],[x,-depth+.25,-1.375],'contact floor return'+(i+1),tin));tails.push(b([.42,1.35,.42],[x,-8.2,-3.1],'actual square solder tail'+(i+1),tin));}else{returns.push(b([.42,.42,3.1],[x,-5.85,1.6],'actual rising right-angle contact'+(i+1),tin));tails.push(b([.42,.42,1.2],[x,-5.85,3.05],'actual through-PCB tail'+(i+1),tin));}}
 const pins=['GND','5V',p.role==='output'?'S-OUT':'S-IN','NC'];const port=host.add(new Port({id,label:id==='grove'?'J1 · IN (back-view left)':id==='out'?'J2 · OUT (back-view right)':'J3 · vertical IN',connector:'grove',position:p.position,quaternion:portQuaternion(p.face),pins:pins.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,.15],order:col=>col+1},hitSize:[10,1,5.1],meta:{role:'visual-connector',face:p.face,physicalRole:p.role,scope:'Four actual contacts and mating ownership only;documentary pin labels,no signal,cascade or electrical forwarding;J3 genericHeader4 in schematic is physically own-photo Grove-form socket'}}));return{frame,parts,floor,back,bridge,contacts,returns,tails,port};}
function leds(host){const packages=[],lenses=[],terminals=[],components=[];for(const pixel of pixels){const{x,y,number}=pixel,white=materials.plastic(0xdedfcf,{roughness:.6}),tin=materials.metal(0xaeb5a2,{roughness:.5}),base=box(host.body,[2,2,.55],[x,y,.775],white,'NeoHEX actual U'+number+' WS2812C-2020 package base'),lipShape=roundedRect(2,2,.06);hole(lipShape,0,0,.62);const lip=solid(host.body,lipShape,.3,[x,y,1.05],white,'NeoHEX U'+number+' real white package lip around encapsulant');packages.push(base,lip);for(const dx of[-.74,.74])for(const dy of[-.74,.74])terminals.push(box(host.body,[.52,.52,.07],[x+dx,y+dy,.535],tin,'NeoHEX U'+number+' actual corner termination'));
 const lens=new THREE.Mesh(new THREE.CylinderGeometry(.6,.6,.35,32).rotateX(Math.PI/2),materials.plastic(0xd9d6bc,{roughness:.3}));lens.name='NeoHEX U'+number+' actual independent RGB encapsulant volume';const led=host.add(new PackageLed({id:'led-'+number,label:'U'+number+' · row'+(pixel.row+1)+' / column'+(pixel.col+1),position:[x,y,1.175],mesh:lens,radius:.6,glowSize:0,color:0xffffff,meta:{role:'externally-driven-visual',part:'WS2812C-2020-V1',reference:'U'+number,row:pixel.row,column:pixel.col,physicalOrder:'Own schematic U1..U37 top-to-bottom,left-to-right;not simulated serial address',scope:'Independent external on/color/brightness only;no firmware,power limit,WS2812 data,automatic animation or cascade'}}));lenses.push(lens);components.push(led);}return{packages,lenses,terminals,components};}
export function buildNeoHex(host,{diffuser=true}={}){if(typeof diffuser!=='boolean')throw new TypeError('diffuser must be boolean');const board=circuit(host),input=socket(host,'grove'),output=socket(host,'out'),vertical=socket(host,'grove-in'),diffuserPort=host.add(new Port({id:'diffuser',label:'Independent opal light sheet',connector:spec.diffuser.connector,position:[0,0,spec.diffuser.seatZmm],quaternion:portQuaternion('front'),hitSize:[30,.25,27],meta:{role:'mechanical-placement',physicalRole:'removable-supplied-sheet',scope:'Sheet placement on actual LED/package tops;not a manufactured connector,latch,hinge or electrical interface'}})),display=leds(host);host.neohexAssembly={board,input,output,vertical,diffuserPort,display};host.unitStickers=addStickers(host);if(diffuser)diffuserPort.attach(new Diffuser());}
